def average_hold_time(data: list, key: str) -> float:
    # Hold time of a press is release_time - press_time.
    holds = [release - press for k, press, release in data if k == key]
    if not holds:
        return 0.0
    return sum(holds) / len(holds)


def average_transition_time(data: list, key1: str, key2: str) -> float:
    # Transition: time from releasing key1 to pressing the next key2.
    transitions = []
    for i in range(len(data) - 1):
        if data[i][0] == key1 and data[i + 1][0] == key2:
            transitions.append(data[i + 1][1] - data[i][2])
    if not transitions:
        return 0.0
    return sum(transitions) / len(transitions)


def get_typed_text(data: list) -> str:
    text = []
    for key, _, _ in data:
        if key == 'BACKSPACE':
            if text:
                text.pop()
        elif key == 'SPACE':
            text.append(' ')
        else:
            text.append(key)
    return ''.join(text)


def words_per_minute(data: list) -> float:
    if not data:
        return 0.0
    # Total time spans from the first press to the last release.
    total_ms = data[-1][2] - data[0][1]
    if total_ms <= 0:
        return 0.0
    words = len(get_typed_text(data).split())
    minutes = total_ms / 60000
    return words / minutes
